import React from 'react';

function MyComponent() {
  return (
    <div>
      <h2>Добро пожаловать в мой компонент!</h2>
      <p>React позволяет создавать переиспользуемые части интерфейса.</p>
    </div>
  );
}

export default MyComponent;
